#!/usr/bin/env node
/**
 * PreToolUse hook: stop Edit / MultiEdit / Write from hand-editing generated files.
 *
 * `pnpm generate:site` rewrites these from the data files and templates, and CI fails on a diff, so
 * a hand edit is lost on the next run (or fails the build). Whole files are blocked; `index.html`
 * and `sitemap.xml` are only partly generated, so an edit is blocked only when the text it replaces
 * sits inside a generated region. Running the generator from Bash is not guarded.
 *
 * Exit 2 blocks the call and sends the message on stderr to Claude. Any problem reading the input
 * lets the call through: this hook must never be the reason an edit cannot happen.
 */

import { readFileSync } from 'node:fs';
import { isAbsolute, relative, sep } from 'node:path';
import process from 'node:process';
import { pathToFileURL } from 'node:url';

/** Whole files and directories that are generated, with where the real source lives. */
export const GENERATED = [
  {
    test: p => p.startsWith('posts/'),
    source: '`posts-data.json` (post pages) or `scripts/templates/`',
  },
  {
    test: p => p.startsWith('projects/'),
    source: '`projects-data.json` or `scripts/templates/project-page.mjs`',
  },
  { test: p => p.startsWith('status/'), source: '`scripts/templates/status-page.mjs`' },
  { test: p => p === 'feed.xml', source: '`posts-data.json` and `scripts/generate-site.mjs`' },
  { test: p => p === 'llms.txt', source: '`scripts/templates/llms.mjs` and the data files' },
  { test: p => p === '404.html', source: '`scripts/templates/`' },
  {
    test: p => /^images\/projects\/.+-cover-(light|dark)\.svg$/.test(p),
    source: '`scripts/generate-site.mjs` (covers for projects without a screenshot)',
  },
  {
    test: p => p === 'github-data.json',
    source: '`update-github-data.yml` / `scripts/update-github-data.py` (written by CI)',
  },
];

/** Files that are generated only between markers: the regions to protect, as [start, end) offsets. */
export const PARTLY_GENERATED = {
  'index.html': text => {
    const regions = [];
    for (const match of text.matchAll(/<!-- gen:(\w+) -->[\s\S]*?<!-- \/gen:\1 -->/g)) {
      regions.push([match.index, match.index + match[0].length]);
    }
    return regions;
  },
  'sitemap.xml': text => {
    const start = text.indexOf('  <!-- Project Pages -->');
    const end = text.indexOf('  <!-- Offline Page (for PWA) -->');
    return start === -1 || end === -1 || end < start ? [] : [[start, end]];
  },
};

const PARTLY_SOURCE =
  'the data files (`projects-data.json`, `experience-data.json`, `posts-data.json`) or `scripts/templates/`';

const overlaps = (text, needle, regions) => {
  if (!needle) return false;
  for (let at = text.indexOf(needle); at !== -1; at = text.indexOf(needle, at + 1)) {
    if (regions.some(([start, end]) => at < end && at + needle.length > start)) return true;
  }
  return false;
};

/**
 * @param {{ root: string, tool_input?: { file_path?: string, old_string?: string, edits?: Array<{ old_string?: string }> } }} call
 * @param {(path: string) => string} read
 * @returns {string | null} why the edit is blocked, or null to allow it
 */
export function blockedReason(
  { root, tool_input: input = {} },
  read = path => readFileSync(path, 'utf8')
) {
  const file = input.file_path;
  if (!file) return null;
  const path = (isAbsolute(file) ? relative(root, file) : file).split(sep).join('/');
  if (path.startsWith('../')) return null;

  const whole = GENERATED.find(entry => entry.test(path));
  if (whole) {
    return `${path} is generated by \`pnpm generate:site\` (or CI) and a hand edit is lost or fails CI. Edit ${whole.source} instead, then run \`pnpm generate:site\`.`;
  }

  const findRegions = PARTLY_GENERATED[path];
  if (!findRegions) return null;
  let text;
  try {
    text = read(isAbsolute(file) ? file : `${root}/${file}`);
  } catch {
    return null;
  }
  const regions = findRegions(text);
  const needles = [input.old_string, ...(input.edits ?? []).map(edit => edit.old_string)];
  if (needles.some(needle => overlaps(text, needle, regions))) {
    return `That edit changes a generated part of ${path} (between the gen: markers, or the project and blog entries in the sitemap). Edit ${PARTLY_SOURCE} instead, then run \`pnpm generate:site\`. Edits outside the generated parts are fine.`;
  }
  return null;
}

async function main() {
  let call;
  try {
    call = JSON.parse(readFileSync(0, 'utf8'));
  } catch {
    return;
  }
  const reason = blockedReason({ ...call, root: process.env.CLAUDE_PROJECT_DIR ?? process.cwd() });
  if (reason) {
    process.stderr.write(`${reason}\n`);
    process.exit(2);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) await main();
